SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT id_evento,nome_evento,data_inicial::date,data_final::date,ativo FROM tb_evento_corridas WHERE data_inicial::date>'2026-10-11' AND (nome_evento ILIKE '%ASSA%' OR nome_evento ILIKE '%TRIMAIS%' OR nome_evento ILIKE '%REIS MAGOS%' OR nome_evento ILIKE '%JURER%' OR nome_evento ILIKE '%MONUMENTAL%'))x))::text payload